mapper.select:
SELECT station.* FROM station INNER JOIN ( SELECT station_purchase.station_id, COUNT(*) AS purchase_count, MAX(station_purchase.paid_at) AS last_purchased_at FROM ( SELECT item.from_station_id AS station_id, payment.paid_at FROM order_item item INNER JOIN ( SELECT order_id, MAX(paid_at) AS paid_at FROM payment_record WHERE status = 'SUCCESS' AND paid_at IS NOT NULL AND paid_at >= TIMESTAMPADD( DAY, -#{recentDays}, NOW() ) GROUP BY order_id ) payment ON payment.order_id = item.order_id WHERE item.status IN ( 'ISSUED', 'REFUNDED', 'CHANGED' )
UNION ALL
SELECT item.to_station_id AS station_id, payment.paid_at FROM order_item item INNER JOIN ( SELECT order_id, MAX(paid_at) AS paid_at FROM payment_record WHERE status = 'SUCCESS' AND paid_at IS NOT NULL AND paid_at >= TIMESTAMPADD( DAY, -#{recentDays}, NOW() ) GROUP BY order_id ) payment ON payment.order_id = item.order_id WHERE item.status IN ( 'ISSUED', 'REFUNDED', 'CHANGED' ) ) station_purchase GROUP BY station_purchase.station_id ) purchase_statistics ON purchase_statistics.station_id = station.id WHERE station.status = 'ACTIVE' AND station.passenger_service = 1 ORDER BY purchase_statistics.purchase_count DESC, purchase_statistics.last_purchased_at DESC, station.name ASC LIMIT #{limit}
